// Filtra apenas a coluna 'novo_lead' e retorna um item por caso
const colunas = $input.first().json;
const novoLead = colunas.find(c => c.etapa === 'novo_lead');
return (novoLead ? novoLead.casos : []).map(caso => ({ json: caso }));

